<script setup lang="ts">import {ref,computed,watch} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import Empty from '../components/common/Empty.vue';import {create} from '../api/shipments';import {useAsync} from '../hooks/useAsync';import {SHIPMENT_CHECKS,MAX_SHIPMENT_HOURS} from '../constants/enums';import DeliveryCurve from '../components/shipment/DeliveryCurve.vue';import ShipmentTable from '../components/shipment/ShipmentTable.vue';import InventoryTable from '../components/shipment/InventoryTable.vue';import ReconTable from '../components/shipment/ReconTable.vue';
const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();
const name=ref(''),runId=ref(''),cargo=ref(100),deadline=ref(24),limits=ref<Record<string,number>>({});
const {busy,error,execute}=useAsync();
const completedRuns=computed(()=>props.data.runs.filter(r=>r.status==='completed'));
const selectedRun=computed(()=>completedRuns.value.find(r=>r.id===(runId.value||completedRuns.value[0]?.id))||completedRuns.value[0]);
const transferNodes=computed(()=>{const r=selectedRun.value;if(!r)return[];return r.result.nodes.map(n=>n.node_id).filter(n=>n!==r.result.source&&n!==r.result.sink);});
// 切换推演时为新出现的中转站填默认上限，已填过的节点保留用户输入
watch(transferNodes,(nodes)=>{const next={...limits.value};nodes.forEach(n=>{if(next[n]===undefined)next[n]=20;});limits.value=next;},{immediate:true});
const activeId=ref('');
const active=computed(()=>props.data.shipments.find(s=>s.id===activeId.value)||props.data.shipments.find(s=>s.status==='completed')||props.data.shipments[0]);
async function submit(){await execute(async()=>{const id=selectedRun.value?.id;if(!id)throw new Error('请先完成一次韧性推演');await create({run_id:id,name:name.value||('限时发运 '+new Date().toLocaleString('zh-CN')),total_cargo:Number(cargo.value),deadline_hours:Number(deadline.value),stock_limits:limits.value});name.value='';await props.refresh();});}
function scenarioName(id:string){return props.data.scenarios.find(s=>s.id===props.data.runs.find(r=>r.id===id)?.scenario_id)?.name||'—';}
</script><template><PageHeading code="07 / TIME-BOUNDED SHIPMENT" title="每小时吞吐之外，回答积压能否按时送达。" :description="`沿用已完成推演的停边快照，整点发车、行程向上取整到小时，截止最长${MAX_SHIPMENT_HOURS}小时；求截止时最多送达量并保存逐小时发运与站内库存。`"/><section class="paper" v-if="canWrite"><h2>发起限时发运分析</h2><Empty v-if="!completedRuns.length">请先在“停用方案”里完成一次韧性推演，再基于其锁定快照发起限时发运。</Empty><form v-else class="grid-form" @submit.prevent="submit"><label>分析名称<input aria-label="分析名称" required minlength="2" v-model="name" placeholder="留空则自动命名"/></label><label>基于已完成推演<select aria-label="选择推演" :value="selectedRun?.id" @change="runId=($event.target as HTMLSelectElement).value"><option v-for="r in completedRuns" :key="r.id" :value="r.id">{{scenarioName(r.id)}} · {{r.created_at.slice(11,19)}}</option></select></label><label>整箱货量 / 箱<input aria-label="整箱货量" type="number" min="1" max="1000000000" required v-model.number="cargo"/></label><label>截止小时 / 小时<input aria-label="截止小时" type="number" min="1" :max="MAX_SHIPMENT_HOURS" required v-model.number="deadline"/></label><fieldset class="wide"><legend>各中转站库存上限 / 箱（源站与汇站不限）</legend><div class="stock-grid"><label v-for="n in transferNodes" :key="n">{{n}}<input type="number" min="0" max="1000000000" required v-model.number="limits[n]"/></label></div></fieldset><Notice v-if="error" error>{{error}}</Notice><button :disabled="busy">入队计算限时发运</button></form></section><section class="paper"><h2>历史限时发运分析</h2><Empty v-if="!data.shipments.length">还没有限时发运分析。</Empty><div class="shipment-tabs" v-else><button v-for="s in data.shipments" :key="s.id" :class="{active:active?.id===s.id}" @click="activeId=s.id"><b>{{s.name}}</b><Status :value="s.status"/></button></div></section><template v-if="active"><Notice v-if="active.status!=='completed'" :error="active.status==='failed'">{{active.status==='failed'?active.error:'后台正在按小时展开网络并保存检查点，结果会自动刷新；未完成前不展示半成品。'}}</Notice><section v-else class="paper result-head"><div><span class="eyebrow">MAX DELIVERED BY DEADLINE</span><h2>{{active.result.max_delivered}} <small>/ {{active.result.total_cargo}} 箱 · 截止 {{active.result.deadline_hours}} 小时</small></h2></div><div class="head-stats"><div><small>未送达</small><b>{{active.result.undelivered}}</b></div><div><small>源 → 汇</small><b>{{active.result.source}} → {{active.result.sink}}</b></div><div><small>停用边</small><b>{{active.result.disabled_arc_ids.length?active.result.disabled_arc_ids.join('、'):'无'}}</b></div></div></section><section v-if="active.status==='completed'" class="paper"><div class="section-heading"><h2>证据自检</h2><span>整数精确核验</span></div><div class="check-strip"><span v-for="(ok,key) in active.result.checks" :key="key" :class="{pass:ok}">{{ok?'✓':'×'}} {{SHIPMENT_CHECKS[key]||key}}</span></div></section><section v-if="active.status==='completed'" class="paper"><h2>逐小时累计送达</h2><DeliveryCurve :series="active.result.delivered_series" :total="active.result.total_cargo"/></section><section v-if="active.status==='completed'" class="paper"><h2>按节点收发与库存对账</h2><p class="caption">源站：总货量=未投放+发出+期末库存；中转站：收到=发出+期末库存；汇站：收到=累计送达+期末库存。</p><ReconTable :rows="active.result.reconciliation"/></section><section v-if="active.status==='completed'" class="paper"><h2>逐小时逐边发运台账</h2><ShipmentTable :rows="active.result.shipments" :deadline="active.result.deadline_hours"/></section><section v-if="active.status==='completed'" class="paper"><h2>逐小时站内库存</h2><InventoryTable :rows="active.result.inventory" :limits="active.result.stock_limits" :source="active.result.source" :sink="active.result.sink"/></section><aside v-if="active.status==='completed'" class="assumptions"><h2>解释边界</h2><p v-for="(a,i) in active.result.assumptions" :key="a"><b>0{{i+1}}</b>{{a}}</p><small>快照校验码 {{active.result.checksum.slice(0,24)}}</small></aside></template></template>
